"""Data model interface for decoupled parsers and writers (AT39 Reduced Coupling)."""
from typing import Protocol, Dict, Any


class DataRecord(Protocol):
    """Minimal interface for serializable domain data exchanged between parsers and writers."""

    def to_dict(self) -> Dict[str, Any]:
        """Return a serializable dict representation."""
        ...


class UserRecord:
    """Minimal User data record conforming to DataRecord interface."""
    __slots__ = ('id', 'nickname', 'gender', 'location', 'birthday', 'description',
                 'verified_reason', 'talent', 'education', 'work', 'weibo_num',
                 'following', 'followers')

    def __init__(self, **kwargs):
        for slot in self.__slots__:
            setattr(self, slot, kwargs.get(slot, '' if slot != 'weibo_num' and slot not in ['following', 'followers'] else 0))

    def to_dict(self) -> Dict[str, Any]:
        return {slot: getattr(self, slot) for slot in self.__slots__ if hasattr(self, slot)}


class WeiboRecord:
    """Minimal Weibo data record conforming to DataRecord interface."""
    __slots__ = ('id', 'user_id', 'content', 'article_url', 'original_pictures',
                 'retweet_pictures', 'original', 'video_url', 'original_pictures_list',
                 'retweet_pictures_list', 'media', 'publish_place', 'publish_time',
                 'publish_tool', 'up_num', 'retweet_num', 'comment_num')

    def __init__(self, **kwargs):
        for slot in self.__slots__:
            setattr(self, slot, kwargs.get(slot, '' if slot != 'original' else True))

    def to_dict(self) -> Dict[str, Any]:
        return {slot: getattr(self, slot) for slot in self.__slots__ if hasattr(self, slot)}
